package bench

import (
	"fmt"
	"math/bits"

	"strix-halo-vulkan/shaders"
	"strix-halo-vulkan/vk"
)

// w4a8Variant is one load width of shaders/gemv_w4a8.comp. VEC=1 reads one
// uint (8 weights) per lane per step, VEC=4 one uvec4 (32 weights) — the
// same kernel otherwise, so the pair isolates load width (IDEAS §1.3) from
// everything else the W4A8 path changes.
type w4a8Variant struct {
	name           string
	spirv          []byte
	weightsPerLoad int
}

var w4a8Variants = []w4a8Variant{
	{name: "subgroup", spirv: shaders.GEMVW4A8, weightsPerLoad: 8},
	{name: "subgroup_vec4", spirv: shaders.GEMVW4A8Vec4, weightsPerLoad: 32},
}

// runGEMVW4A8 measures y = W*x with 4-bit weights and int8 activations, both
// fed to the packed-int8 dot instruction (shaders/gemv_w4a8.comp). This is
// IDEAS.md §1.1: same bytes as the PRECISION_Q4 path, same arithmetic as
// the W8A8 path.
func runGEMVW4A8(dev *vk.Device, sizes []int, blocks []int, warmup, iters uint32) ([]Result, error) {
	var results []Result
	for _, v := range w4a8Variants {
		mod, err := dev.NewShaderModule(v.spirv)
		if err != nil {
			return nil, err
		}
		defer mod.Destroy()

		for _, block := range blocks {
			if !w4a8BlockOK(block, v.weightsPerLoad) {
				continue
			}
			if err := verifyGEMVW4A8(dev, mod, block); err != nil {
				return nil, fmt.Errorf("gemv %s w4a8 block=%d correctness check: %w", v.name, block, err)
			}
			for _, n := range sizes {
				M, N := n, n
				if N%block != 0 || N%v.weightsPerLoad != 0 {
					continue
				}
				res, err := timeGEMVW4A8(dev, mod, v, M, N, block, warmup, iters)
				if err != nil {
					return nil, fmt.Errorf("gemv %s w4a8 block=%d size=%d: %w", v.name, block, n, err)
				}
				results = append(results, res)
			}
		}
	}
	return results, nil
}

// w4a8BlockOK reports whether a quantization block size is usable by the
// kernel: it must be a power of two (the shader shifts by log2(block)
// instead of dividing, IDEAS §1.2) and at least one load wide, so that a
// load's worth of weights never straddles two scales.
func w4a8BlockOK(block, weightsPerLoad int) bool {
	return block >= weightsPerLoad && block&(block-1) == 0
}

func log2u(v int) uint32 {
	return uint32(bits.TrailingZeros(uint(v)))
}

// gemvW4A8PushConstants packs {M,N,logBlock,xScale} matching gemv_w4a8.comp.
func gemvW4A8PushConstants(M, N, block int, xScale float32) []byte {
	return newPC().U32(uint32(M)).U32(uint32(N)).U32(log2u(block)).F32(xScale).Bytes()
}

// w4a8Buffers is one W4A8 GEMV's device-side state. The activation-side
// buffers (x and its per-block sums) are what a real engine would produce
// per token from the previous layer's output.
type w4a8Buffers struct {
	w, scales, x, y, xSums *vk.Buffer
	xScale                 float32
}

func (b *w4a8Buffers) destroy() {
	for _, buf := range []*vk.Buffer{b.w, b.scales, b.x, b.y, b.xSums} {
		if buf != nil {
			buf.Destroy()
		}
	}
}

func (b *w4a8Buffers) list() []*vk.Buffer {
	return []*vk.Buffer{b.w, b.scales, b.x, b.y, b.xSums}
}

func buildGEMVW4A8Buffers(dev *vk.Device, M, N, block int) (bufs w4a8Buffers, xData []float32, packedW []uint8, wScales []uint16, err error) {
	wData := randomFloats(M * N)
	packedW, wScales = quantizeQ4(wData, M, N, block)
	words := repackQ4ToW4A8(packedW, M, N)

	if bufs.w, err = dev.NewBuffer(len(words) * 4); err != nil {
		return
	}
	bufs.w.WriteBytes(uint32SliceToBytes(words))

	if bufs.scales, err = dev.NewBuffer(len(wScales) * 2); err != nil {
		return
	}
	bufs.scales.WriteBytes(float16SliceToBytes(wScales))

	xData = randomFloats(N)
	packedX, xScales := quantizeQ8(xData, 1, N, N) // one scale for the whole vector
	bufs.xScale = float16ToFloat32(xScales[0])

	if bufs.x, err = dev.NewBuffer(len(packedX)); err != nil {
		return
	}
	bufs.x.WriteBytes(int8SliceToBytes(packedX))

	sums := int8BlockSums(packedX, block)
	if bufs.xSums, err = dev.NewBuffer(len(sums) * 4); err != nil {
		return
	}
	bufs.xSums.WriteBytes(int32SliceToBytes(sums))

	bufs.y, err = dev.NewBuffer(M * 4)
	return
}

func verifyGEMVW4A8(dev *vk.Device, mod *vk.ShaderModule, block int) error {
	n := gemmCorrectnessSize
	if n%block != 0 {
		n = block * 2
	}
	M, N := n, n

	bufs, xData, packedW, wScales, err := buildGEMVW4A8Buffers(dev, M, N, block)
	defer bufs.destroy()
	if err != nil {
		return err
	}

	pipe, err := dev.NewPipeline(mod, vk.PipelineSpec{
		Buffers:          bufs.list(),
		PushConstantSize: 16,
	})
	if err != nil {
		return err
	}
	defer pipe.Destroy()

	pc := gemvW4A8PushConstants(M, N, block, bufs.xScale)
	if _, err := pipe.DispatchTimed(uint32(M), 1, 1, 1, pc); err != nil {
		return err
	}
	got := bufs.y.ReadFloat32(M)

	// The reference is built from the *pre-repack* Q4 arrays, so it checks
	// repackQ4ToW4A8's permutation as well as the kernel.
	refW := dequantizeQ4(packedW, wScales, M, N, block)
	packedX, xScales := quantizeQ8(xData, 1, N, N)
	refX := dequantizeQ8(packedX, xScales, 1, N, N)
	want := cpuGEMV(refW, refX, M, N)
	return compareVec(got, want, 2e-2)
}

func timeGEMVW4A8(dev *vk.Device, mod *vk.ShaderModule, v w4a8Variant, M, N, block int, warmup, iters uint32) (Result, error) {
	bufs, _, _, _, err := buildGEMVW4A8Buffers(dev, M, N, block)
	defer bufs.destroy()
	if err != nil {
		return Result{}, err
	}

	pipe, err := dev.NewPipeline(mod, vk.PipelineSpec{
		Buffers:          bufs.list(),
		PushConstantSize: 16,
	})
	if err != nil {
		return Result{}, err
	}
	defer pipe.Destroy()

	pc := gemvW4A8PushConstants(M, N, block, bufs.xScale)
	groupsX := uint32(M)

	ns, clocks, err := TimeDispatch(pipe, groupsX, 1, 1, warmup, iters, pc)
	if err != nil {
		return Result{}, err
	}

	weightBytes := float64(M*N)/2 + float64((M*N/block)*2)
	flops := float64(2 * M * N)
	return Result{
		Op: "gemv", Variant: v.name, WeightFormat: "w4a8", BlockSize: block, Size: N,
		NsPerIter: ns,
		Clocks:    clocks,
		GFLOPS:    flops / (ns / 1e9) / 1e9,
		GBPS:      weightBytes / (ns / 1e9) / 1e9,
	}, nil
}
===== cmd/bench/main.go =====
// Command bench runs the Vulkan compute benchmark suite for
// neural-network-inference-shaped operations (GEMM, GEMV, elementwise,
// reductions) across implementation flavours (naive/tiled/subgroup/
// cooperative-matrix; fp32/fp16/int8/int4 weights) on the local GPU,
// picking the Strix Halo iGPU if present.
package main

import (
	"flag"
	"fmt"
	"log"
	"os"
	"strconv"
	"strings"
	"time"

	"strix-halo-vulkan/bench"
	"strix-halo-vulkan/vk"
)

const strixHaloDeviceID = 0x1586

func main() {
	sizesFlag := flag.String("sizes", "256,512,1024,2048,4096", "comma-separated matrix/vector dimensions to sweep (gemv, gemm, reductions)")
	// Each bandwidth/elementwise element is one fp32 read plus one fp32
	// write, so the footprint touched per iteration is 8 bytes per element:
	// this list runs from 2MB up to 512MB, deliberately fine-grained around
	// this chip's ~32MB last-level cache so the cache-to-DRAM cliff can be
	// located rather than merely straddled.
	bwSizesFlag := flag.String("bwsizes", "262144,524288,1048576,2097152,3145728,4194304,6291456,8388608,12582912,16777216,33554432,67108864", "comma-separated element counts to sweep for bandwidth/elementwise (footprint per iteration is 8 bytes/element; needs millions of elements to leave the dispatch-overhead-bound regime and reach steady-state memory bandwidth)")
	blocksFlag := flag.String("blocks", "32,64,128", "comma-separated quantization block sizes to sweep")
	warmup := flag.Uint("warmup", 3, "untimed warmup dispatches before each timed measurement")
	iters := flag.Uint("iters", 20, "back-to-back timed dispatches averaged per measurement")
	csvPath := flag.String("csv", "", "optional path to write results as CSV")
	skip := flag.String("skip", "", "comma-separated op families to skip (peak,overhead,bandwidth,elementwise,gemv,gemv_cold,gemm,reduce)")
	coldFootprintsFlag := flag.String("coldfootprints", "16,64,256", "comma-separated weight footprints in MB (fp16-equivalent) for the DRAM-resident gemv_cold sweep; entries well above the ~32MB last-level cache are the ones that measure real decode")
	coldN := flag.Int("coldn", 4096, "reduction length N for the gemv_cold sweep; its row count M is derived from each footprint")
	warmClock := flag.Duration("warmclock", 3*time.Second, "maximum ALU-heavy warmup before each timed measurement; stops as soon as the GPU reaches its top advertised clock, so a hot GPU costs one short burst (0 disables)")
	clockSample := flag.Duration("clocksample", time.Millisecond, "sampling period for the sclk/power counters recorded with each measurement")
	cus := flag.Int("cus", 40, "compute-unit count, used only to express the measured peak rates as ops/clock/CU")
	flag.Parse()

	sizes, err := parseInts(*sizesFlag)
	if err != nil {
		log.Fatalf("-sizes: %v", err)
	}
	bwSizes, err := parseInts(*bwSizesFlag)
	if err != nil {
		log.Fatalf("-bwsizes: %v", err)
	}
	blocks, err := parseInts(*blocksFlag)
	if err != nil {
		log.Fatalf("-blocks: %v", err)
	}
	coldFootprints, err := parseInts(*coldFootprintsFlag)
	if err != nil {
		log.Fatalf("-coldfootprints: %v", err)
	}
	skipSet := map[string]bool{}
	for _, s := range strings.Split(*skip, ",") {
		if s = strings.TrimSpace(s); s != "" {
			skipSet[s] = true
		}
	}

	cfg := config{
		sizes: sizes, bwSizes: bwSizes, blocks: blocks,
		coldFootprints: coldFootprints, coldN: *coldN,
		warmup: uint32(*warmup), iters: uint32(*iters),
		warmClock: *warmClock, clockSample: *clockSample, cus: *cus,
		csvPath: *csvPath, skip: skipSet,
	}
	if err := run(cfg); err != nil {
		log.Fatal(err)
	}
}

func parseInts(s string) ([]int, error) {
	var out []int
	for _, part := range strings.Split(s, ",") {
		part = strings.TrimSpace(part)
		if part == "" {
			continue
		}
		v, err := strconv.Atoi(part)
		if err != nil {
			return nil, fmt.Errorf("%q: %w", part, err)
		}
		out = append(out, v)
	}
	return out, nil
}

// config is one invocation's worth of sweep parameters, gathered into a
// struct because run's parameter list had outgrown being readable.
type config struct {
	sizes, bwSizes, blocks []int
	coldFootprints         []int
	coldN                  int
	warmup, iters          uint32
	warmClock, clockSample time.Duration
	cus                    int
	csvPath                string
	skip                   map[string]bool
}

func run(cfg config) error {
	instance, err := vk.NewInstance("strix-halo-bench")
	if err != nil {
		return err
	}
	defer instance.Destroy()

	devices, err := instance.PhysicalDevices()
	if err != nil {
		return err
	}
	phys := pickDevice(devices)
	fmt.Printf("device: %s (vendor 0x%04x, device 0x%04x)\n", phys.Name, phys.VendorID, phys.DeviceID)

	feat, err := phys.SupportedFeatures()
	if err != nil {
		return err
	}
	fmt.Printf("features: fp16=%v int8=%v integerDotProduct=%v coopMatrix=%v\n",
		feat.Float16, feat.Int8, feat.IntegerDotProduct, feat.CoopMatrix)

	queueFamily, err := phys.ComputeQueueFamily()
	if err != nil {
		return err
	}
	dev, err := vk.NewDevice(phys, queueFamily, vk.DeviceFeatures{
		Float16: true, Int8: true, IntegerDotProduct: true, CoopMatrix: true,
	})
	if err != nil {
		return err
	}
	defer dev.Destroy()

	// Instrumentation is installed before any measurement: it both lifts
	// the GPU off its idle clock ahead of each timed batch and records the
	// clock alongside every result, so a number taken at a low clock is
	// visible as such instead of looking like a slow kernel.
	inst, err := bench.NewInstruments(dev, cfg.warmClock, cfg.clockSample)
	if err != nil {
		return err
	}
	defer inst.Destroy()
	bench.SetInstruments(inst)

	fmt.Printf("sweeping sizes=%v bwsizes=%v blocks=%v warmup=%d iters=%d\n", cfg.sizes, cfg.bwSizes, cfg.blocks, cfg.warmup, cfg.iters)
	fmt.Printf("instrumentation: %s\n\n", inst.Describe())

	var results []bench.Result
	run := func(name string, fn func() ([]bench.Result, error)) error {
		if cfg.skip[name] {
			fmt.Printf("== %s (skipped) ==\n", name)
			return nil
		}
		fmt.Printf("== %s ==\n", name)
		r, err := fn()
		if err != nil {
			return fmt.Errorf("%s: %w", name, err)
		}
		bench.PrintTable(os.Stdout, r)
		fmt.Println()
		results = append(results, r...)
		return nil
	}

	// peak and overhead run first: they establish the ceiling and the floor
	// that every subsequent number should be read against.
	if err := run("peak", func() ([]bench.Result, error) { return bench.RunPeak(dev, phys, cfg.warmup, cfg.iters) }); err != nil {
		return err
	}
	bench.PrintPeakSummary(os.Stdout, results, cfg.cus)
	if len(results) > 0 {
		fmt.Println()
	}
	if err := run("overhead", func() ([]bench.Result, error) { return bench.RunOverhead(dev, cfg.warmup, cfg.iters) }); err != nil {
		return err
	}
	if err := run("bandwidth", func() ([]bench.Result, error) { return bench.RunBandwidth(dev, cfg.bwSizes, cfg.warmup, cfg.iters) }); err != nil {
		return err
	}
	if err := run("elementwise", func() ([]bench.Result, error) { return bench.RunElementwise(dev, cfg.bwSizes, cfg.warmup, cfg.iters) }); err != nil {
		return err
	}
	if err := run("gemv", func() ([]bench.Result, error) {
		return bench.RunGEMV(dev, phys, cfg.sizes, cfg.blocks, cfg.warmup, cfg.iters)
	}); err != nil {
		return err
	}
	if err := run("gemv_cold", func() ([]bench.Result, error) {
		return bench.RunGEMVCold(dev, phys, cfg.coldFootprints, cfg.coldN, cfg.blocks, cfg.warmup, cfg.iters)
	}); err != nil {
		return err
	}
	if err := run("gemm", func() ([]bench.Result, error) {
		return bench.RunGEMM(dev, phys, cfg.sizes, cfg.blocks, cfg.warmup, cfg.iters)
	}); err != nil {
		return err
	}
	if err := run("reduce", func() ([]bench.Result, error) { return bench.RunReductions(dev, cfg.sizes, cfg.warmup, cfg.iters) }); err != nil {
		return err
	}

	if cfg.csvPath != "" {
		if err := bench.WriteCSV(cfg.csvPath, results); err != nil {
			return err
		}
		fmt.Printf("wrote %d results to %s\n", len(results), cfg.csvPath)
	}
	return nil
}

// pickDevice prefers the Strix Halo iGPU by deviceID, falling back to the
// first device the instance reports.
func pickDevice(devices []vk.PhysicalDevice) *vk.PhysicalDevice {
	for i := range devices {
		if devices[i].DeviceID == strixHaloDeviceID {
			return &devices[i]
		}
	}
	return &devices[0]
}

